def test_free_form_objects():
    """Test that objects with only 'type: object' are treated as free-form."""

    open_bldr = OpenApiBuilder()

    # Define a schema with a free-form object property (tags)
    @open_bldr.component.schema
    class Pet:
        """A pet with free-form tags."""

        @open_bldr.component.schema_field
        def name(self) -> str:
            """Pet's name"""

        @open_bldr.component.schema_field  
        def tags(self) -> object:
            """Custom tags - should be a free-form object"""
            # According to OpenAPI 3 spec, this should be equivalent to:
            # type: object, additionalProperties: true
            # or type: object, additionalProperties: {}

    # Build the OpenAPI spec
    spec_dict = open_bldr.dict()

    # Check if the tags property is correctly defined as a free-form object
    pet_schema = spec_dict['components']['schemas']['Pet']
    tags_property = pet_schema['properties']['tags']

    print("Generated Pet schema:")
    print(pet_schema)
    print()

    print("Tags property:")
    print(tags_property)
    print()

    # According to OpenAPI 3 spec, a free-form object should have:
    # type: object and either additionalProperties: true or additionalProperties: {}
    # OR just type: object (which implies additionalProperties: true)

    if tags_property.get('type') == 'object':
        print("✓ Tags property has type: object")

        # Check if it allows additional properties (free-form)
        additional_props = tags_property.get('additionalProperties')
        if additional_props is True or additional_props == {} or additional_props is None:
            print("✓ Tags property is correctly defined as free-form object")
            return True
        else:
            print(f"✗ Tags property has unexpected additionalProperties: {additional_props}")
            return False
    else:
        print(f"✗ Tags property doesn't have type: object, got: {tags_property.get('type')}")
        return False


