        """Explicit free-form object."""

        @open_bldr.component.schema_field(additionalProperties=True)
        def data(self) -> object:
            """Explicitly free-form data"""

    spec_dict = open_bldr.dict()

    print("Generated ExplicitFreeForm schema:")
    schema = spec_dict['components']['schemas']['ExplicitFreeForm']
    print(schema)
    print()

    data_property = schema['properties']['data']
    additional_props = data_property.get('additionalProperties')

    if additional_props is True:
        print("✓ Explicit additionalProperties=True works")
        return True
    else:
        print(f"✗ Expected additionalProperties=True, got: {additional_props}")
        return False


